SELECT "t8"."order_number", "t8"."line_no", "t8"."item", "t8"."unit_price", "t8"."list_price", 'hold_sales' AS "route", 'price_differences' AS "context"
FROM (SELECT "order_number0" AS "order_number", "line_no0" AS "line_no", "item", "unit_price", "price" AS "list_price"
        FROM (SELECT "t1"."order_number", "t1"."line_no", "t1"."item", "t1"."unit_price", "t1"."customer", "t1"."channel", "t1"."placed_date", "t5"."order_number" AS "order_number0", "t5"."line_no" AS "line_no0", "t5"."price"
                FROM (SELECT "sales_line"."order_number", "sales_line"."line_no", "sales_line"."item", "sales_line"."unit_price", "t0"."customer", "t0"."channel", "t0"."placed_date"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                    INNER JOIN (SELECT "t4"."order_number", "t4"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                        FROM (SELECT "sales_line0"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t3"."customer", "t3"."channel", "t3"."placed_date"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t3"
                                    INNER JOIN "sales_line" AS "sales_line0" ON "t3"."order_number" = "sales_line0"."order_number") AS "t4"
                            LEFT JOIN "customer_price" ON "t4"."item" = "customer_price"."item" AND "t4"."customer" = "customer_price"."customer" AND "t4"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t4"."placed_date" <= "customer_price"."valid_to")
                            LEFT JOIN "price_list" ON "t4"."item" = "price_list"."item" AND "t4"."channel" = "price_list"."channel" AND "t4"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t4"."placed_date" <= "price_list"."valid_to")) AS "t5" ON "t1"."order_number" = "t5"."order_number" AND "t1"."line_no" = "t5"."line_no") AS "t6"
        WHERE "t6"."price" IS NULL OR ABS("t6"."unit_price" - "t6"."price") > :tolerance) AS "t8"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t37"."order_number", "t37"."customer", "t37"."channel", "t37"."fulfilling_warehouse", "t37"."value", "t37"."placed_date", "t37"."state", COALESCE("t37"."n_short", 0) AS "n_short", COALESCE("t37"."n_price", 0) AS "n_price", COALESCE("t43"."n_due", 0) AS "n_due"
                FROM (SELECT "t25"."order_number", "t25"."customer", "t25"."channel", "t25"."fulfilling_warehouse", "t25"."value", "t25"."placed_date", "t25"."state", "t25"."n_short", "t36"."n_price"
                        FROM (SELECT "t10"."order_number", "t10"."customer", "t10"."channel", "t10"."fulfilling_warehouse", "t10"."value", "t10"."placed_date", "t10"."state", "t24"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t10"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t19"."order_number", "t19"."customer", "t19"."channel", "t19"."fulfilling_warehouse", "t19"."value", "t19"."placed_date", "t19"."state", "t19"."line_no", "t19"."item", "t19"."quantity", "t19"."unit_price", "t19"."ext_sales_price", "t19"."warehouse", "t19"."sold_date", "t19"."customer0", "t19"."channel0", "t19"."as_of_date", "t19"."quantity_on_hand", "t19"."_ttrp_g_n8_0", "t19"."_ttrp_g_n8_1", "t19"."_ttrp_latest_n8", "t20"."warehouse" AS "warehouse0", "t20"."from_date", "t20"."to_date", "t20"."reason", COALESCE("t19"."quantity_on_hand", 0) AS "on_hand", "t20"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t13"."order_number", "t13"."customer", "t13"."channel", "t13"."fulfilling_warehouse", "t13"."value", "t13"."placed_date", "t13"."state", "t13"."line_no", "t13"."item", "t13"."quantity", "t13"."unit_price", "t13"."ext_sales_price", "t13"."warehouse", "t13"."sold_date", "t13"."customer0", "t13"."channel0", "t18"."as_of_date", "t18"."quantity_on_hand", "t18"."_ttrp_g_n8_0", "t18"."_ttrp_g_n8_1", "t18"."_ttrp_latest_n8"
                                                        FROM (SELECT "t12"."order_number", "t12"."customer", "t12"."channel", "t12"."fulfilling_warehouse", "t12"."value", "t12"."placed_date", "t12"."state", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."quantity", "sales_line1"."unit_price", "sales_line1"."ext_sales_price", "sales_line1"."warehouse", "sales_line1"."sold_date", "sales_line1"."customer" AS "customer0", "sales_line1"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t12"
                                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t12"."order_number" = "sales_line1"."order_number") AS "t13"
                                                            LEFT JOIN (SELECT *
                                                                FROM (SELECT "t14"."as_of_date", "t14"."item", "t14"."warehouse", "t14"."quantity_on_hand", "t14"."_ttrp_g_n8_0", "t14"."_ttrp_g_n8_1", "t16"."_ttrp_latest_n8"
                                                                        FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1"
                                                                                FROM "inventory") AS "t14"
                                                                            INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", MAX("as_of_date") AS "_ttrp_latest_n8"
                                                                                FROM "inventory"
                                                                                GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t16" ON "t14"."_ttrp_g_n8_0" = "t16"."_ttrp_g_n8_0" AND "t14"."_ttrp_g_n8_1" = "t16"."_ttrp_g_n8_1") AS "t17"
                                                                WHERE "t17"."as_of_date" = "t17"."_ttrp_latest_n8" OR "t17"."_ttrp_latest_n8" IS NULL) AS "t18" ON "t13"."item" = "t18"."item" AND "t13"."warehouse" = "t18"."warehouse") AS "t19"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t20" ON "t19"."warehouse" = "t20"."warehouse") AS "t21"
                                        WHERE "t21"."outage" OR "t21"."on_hand" < "t21"."quantity"
                                        GROUP BY "order_number") AS "t24" ON "t10"."order_number" = "t24"."order_number") AS "t25"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t28"."order_number", "t28"."line_no", "t28"."item", "t28"."unit_price", "t28"."customer", "t28"."channel", "t28"."placed_date", "t32"."order_number" AS "order_number0", "t32"."line_no" AS "line_no0", "t32"."price"
                                        FROM (SELECT "sales_line2"."order_number", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."unit_price", "t27"."customer", "t27"."channel", "t27"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t27"
                                                    INNER JOIN "sales_line" AS "sales_line2" ON "t27"."order_number" = "sales_line2"."order_number") AS "t28"
                                            INNER JOIN (SELECT "t31"."order_number", "t31"."line_no", COALESCE("customer_price0"."price", "price_list0"."price") AS "price"
                                                FROM (SELECT "sales_line3"."order_number", "sales_line3"."line_no", "sales_line3"."item", "sales_line3"."unit_price", "t30"."customer", "t30"."channel", "t30"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t30"
                                                            INNER JOIN "sales_line" AS "sales_line3" ON "t30"."order_number" = "sales_line3"."order_number") AS "t31"
                                                    LEFT JOIN "customer_price" AS "customer_price0" ON "t31"."item" = "customer_price0"."item" AND "t31"."customer" = "customer_price0"."customer" AND "t31"."placed_date" >= "customer_price0"."valid_from" AND ("customer_price0"."valid_to" IS NULL OR "t31"."placed_date" <= "customer_price0"."valid_to")
                                                    LEFT JOIN "price_list" AS "price_list0" ON "t31"."item" = "price_list0"."item" AND "t31"."channel" = "price_list0"."channel" AND "t31"."placed_date" >= "price_list0"."valid_from" AND ("price_list0"."valid_to" IS NULL OR "t31"."placed_date" <= "price_list0"."valid_to")) AS "t32" ON "t28"."order_number" = "t32"."order_number" AND "t28"."line_no" = "t32"."line_no") AS "t33"
                                WHERE "t33"."price" IS NULL OR ABS("t33"."unit_price" - "t33"."price") > :tolerance
                                GROUP BY "order_number0") AS "t36" ON "t25"."order_number" = "t36"."order_number") AS "t37"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t39"."order_number", "t39"."customer", "t39"."channel", "t39"."fulfilling_warehouse", "t39"."value", "t39"."placed_date", "t39"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t39"
                                    INNER JOIN "invoice" ON "t39"."customer" = "invoice"."customer") AS "t40"
                        WHERE "t40"."status" = 'open' AND "t40"."due" < :as_of
                        GROUP BY "order_number") AS "t43" ON "t37"."order_number" = "t43"."order_number") AS "t44"
        WHERE "t44"."n_short" > 0 OR "t44"."n_price" > 0
        GROUP BY "order_number") AS "t47" ON "t8"."order_number" = "t47"."order_number"
